float calculerDistanceTorsionGyrus(vec3 positionEspace) {
    positionEspace.xy *= mat2(cos(positionEspace.z * 0.1 + vec4(0.0, 33.0, 11.0, 0.0)));
    return length(sin(positionEspace) + cos(positionEspace.zxy)) - 0.5;
}

vec3 calculerNormaleGeometrie(vec3 positionEspace) {
    vec2 decalageEpsilon = vec2(0.001, 0.0);
    return normalize(vec3(
        calculerDistanceTorsionGyrus(positionEspace + decalageEpsilon.xyy) - calculerDistanceTorsionGyrus(positionEspace - decalageEpsilon.xyy),
        calculerDistanceTorsionGyrus(positionEspace + decalageEpsilon.yxy) - calculerDistanceTorsionGyrus(positionEspace - decalageEpsilon.yxy),
        calculerDistanceTorsionGyrus(positionEspace + decalageEpsilon.yyx) - calculerDistanceTorsionGyrus(positionEspace - decalageEpsilon.yyx)
    ));
}

void mainImage(out vec4 couleurFragment, vec2 coordonneeFragment) {
    vec3 resolutionEcran = iResolution;

    vec3 positionOrigineRayon = vec3(2.0 * sin(iTime * 0.5), cos(iTime * 0.3), iTime);
    vec3 positionCibleCamera = positionOrigineRayon + vec3(sin(iTime * 0.2), cos(iTime * 0.15), 2.0);

    vec3 axeDirectionAvant = normalize(positionCibleCamera - positionOrigineRayon);
    vec3 axeDirectionDroite = normalize(cross(axeDirectionAvant, vec3(0.0, 1.0, 0.0)));
    vec3 axeDirectionHaut = normalize(cross(axeDirectionDroite, axeDirectionAvant));

    vec2 coordonneesUV = (coordonneeFragment - 0.5 * resolutionEcran.xy) / resolutionEcran.y;
    vec3 directionRayon = normalize(coordonneesUV.x * axeDirectionDroite + coordonneesUV.y * axeDirectionHaut + 1.5 * axeDirectionAvant);

    vec3 positionCouranteRayon = positionOrigineRayon;
    float distanceParcourueTotal = 0.0;

    for (int etapeMarchage = 0; etapeMarchage < 64; etapeMarchage++) {
        positionCouranteRayon = positionOrigineRayon + directionRayon * distanceParcourueTotal;
        vec3 positionTransformee = positionCouranteRayon;
        positionTransformee.xy *= mat2(cos(positionTransformee.z * 0.1 + vec4(0.0, 33.0, 11.0, 0.0)));

        float distanceEstimationSurface = length(sin(positionTransformee) + cos(positionTransformee.zxy)) - 0.5;
        if (distanceEstimationSurface < 0.001 || distanceParcourueTotal > 20.0) break;
        distanceParcourueTotal += distanceEstimationSurface * 0.5;
    }

    vec3 couleurComposee = vec3(0.0);

    if (distanceParcourueTotal < 20.0) {
        vec3 positionImpactSurface = positionOrigineRayon + directionRayon * distanceParcourueTotal;
        vec3 normaleSurface = calculerNormaleGeometrie(positionImpactSurface);

        vec3 positionSourceLumiere = vec3(2.0 * sin(iTime * 0.8), cos(iTime * 0.5), positionOrigineRayon.z + 3.5 + sin(iTime * 1.2) * 1.5);
        vec3 directionVersLumiere = positionSourceLumiere - positionImpactSurface;
        float distanceVersLumiere = length(directionVersLumiere);
        directionVersLumiere /= distanceVersLumiere;

        float attenuationDistanceLumiere = 1.0 / (1.0 + 0.1 * distanceVersLumiere + 0.03 * distanceVersLumiere * distanceVersLumiere);

        float composanteDiffuse = max(0.0, dot(normaleSurface, directionVersLumiere));
        float composanteSpeculaire = pow(max(0.0, dot(reflect(-directionVersLumiere, normaleSurface), -directionRayon)), 32.0);

        float motifTextureVolumetrique = sin(positionImpactSurface.x * 4.0) * cos(positionImpactSurface.y * 4.0) * sin(positionImpactSurface.z * 4.0);
        vec3 couleurAlbedoSurface = mix(vec3(0.2, 0.35, 0.6), vec3(0.7, 0.85, 1.0), smoothstep(-0.2, 0.2, motifTextureVolumetrique));

        float ondeLumineuseOndulante = sin(positionImpactSurface.z * 2.5 - iTime * 4.0) * 0.5 + 0.5;
        vec3 couleurOndeLumineuse = mix(vec3(0.2, 0.5, 1.0), vec3(1.0, 0.6, 0.2), ondeLumineuseOndulante);

        vec3 lumiereAmbiante = vec3(0.18, 0.22, 0.3);
        vec3 lumiereDiffuse = couleurAlbedoSurface * composanteDiffuse * vec3(1.4, 1.3, 1.1) * attenuationDistanceLumiere * 2.8;
        vec3 lumiereSpeculaire = vec3(1.0, 0.9, 0.75) * composanteSpeculaire * attenuationDistanceLumiere * 2.5;
        vec3 pulsionEmissionLumineuse = couleurOndeLumineuse * ondeLumineuseOndulante * 0.8 * attenuationDistanceLumiere;

        couleurComposee = lumiereAmbiante + lumiereDiffuse + lumiereSpeculaire + pulsionEmissionLumineuse;
    } else {
        couleurComposee = vec3(0.08, 0.1, 0.16);
    }

    couleurComposee = mix(couleurComposee, vec3(0.08, 0.1, 0.16), 1.0 - exp(-distanceParcourueTotal * 0.06));
    couleurComposee = pow(couleurComposee, vec3(0.4545));

    couleurFragment = vec4(couleurComposee, 1.0);
}
